      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-inpage-translator\",\n  \"version\": \"0.2.4\",\n  \"description\": \"Translate the whole page you are looking at: a floating button lives in every browser page the agent opens (auto-injected, survives navigation, remembers where you dragged it), hold it to drag, drop it near an edge and it tucks into a small handle. Click it and every visible text node is replaced in place; click again to see the original. String-level cache and parallel chunks make a second pass almost instant.\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./constants\": \"./lib/constants.js\",\n    \"./text-chunks\": \"./lib/text-chunks.js\",\n    \"./page-script\": \"./lib/page-script.js\",\n    \"./translate\": \"./lib/translate.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"translate\",\n    \"translation\",\n    \"in-page\",\n    \"page-translation\",\n    \"browser\",\n    \"bilingual\",\n    \"reader\",\n    \"i18n\",\n    \"翻译\",\n    \"网页翻译\",\n    \"整页翻译\"\n  ],\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"scripts\": {\n    \"test\": \"node test/smoke.mjs\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/7gzgn/dsh-inpage-translator.git\"\n  },\n  \"homepage\": \"https://github.com/7gzgn/dsh-inpage-translator#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/7gzgn/dsh-inpage-translator/issues\"\n  },\n  \"dsh\": {\n    \"compatibility\": {\n      \"dshReleases\": {\n        \"0.2.0-rc.2\": \"compatible\",\n        \"0.2.1-rc.2\": \"compatible\"\n      }\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \">=4.0.4 <5.0.0\",\n    \"@deepseek-ai/dsh-system-prompt\": \">=0.2.0-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-tools\": \">=0.2.0-rc.2 <0.3.0-0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-system-prompt\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-tools\": {\n      \"optional\": true\n    }\n  }\n}\n"
